
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_vt84f_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_vt84f", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([1.084445664705734e+02, 1.050834667743678e+02, 1.005025147499962e+02, 9.440281826993180e+01, 8.654316975627371e+01, 7.686075086806416e+01, 6.559072661048403e+01, 5.317261631197063e+01, 3.969873698963416e+01, 2.615376325576037e+01, 1.417392118046745e+01, 3.232196010892101e+00, 2.042613229692510e+00, 1.718902199756204e+00, 1.249479954379697e+00, 8.293338693449364e-01, 7.107429077952341e-01, 6.483168084336491e-01, 6.034972665502187e-01, 5.743491734508946e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


